code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the smallest likely period from repeated horizontal comparisons.
    period = 1
    for p in range(1, min(10, w - 3) + 1):
        matches = total = 0
        for r in range(3, h):
            for c in range(3 + p, w):
                if grid[r][c] and grid[r][c - p]:
                    total += 1
                    matches += grid[r][c] == grid[r][c - p]
        if total and matches / total >= 0.95:
            period = p
            break

    # Select the longest uninterrupted periodic segment to define the cycle.
    best_len, cycle, cycle_col = -1, None, 3
    for r in range(3, h):
        c = 3
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            vals = []
            while c < w and grid[r][c] != 0:
                vals.append(grid[r][c]); c += 1
            for i in range(len(vals)):
                j = i + period
                while j < len(vals) and vals[j] == vals[j - period]:
                    j += 1
                if j - i > best_len and j - i >= period:
                    best_len = j - i
                    cycle = vals[i:i + period]
                    cycle_col = start + i
    if cycle is None:
        raise ValueError("Could not infer the repeating color cycle")

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                best_offset, best_score = 0, -1
                for off in range(period):
                    score = sum(
                        grid[r][x] == cycle[(x - cycle_col + off) % period]
                        for x in range(3, w) if grid[r][x] != 0
                    )
                    if score > best_score:
                        best_offset, best_score = off, score
                out[r][c] = cycle[(c - cycle_col + best_offset) % period]
    return out
'''
